This adds the closing tags needed to make a fragment well-formed. Assume every closing tag has a matching opening tag earlier in the string. What does it log?

```js
function fixTags(html) {
  const stack = [];
  let out = '';
  for (const tok of html.match(/<\/?\w+>|[^<]+/g)) {
    const open = /^<(\w+)>$/.exec(tok);
    const close = /^<\/(\w+)>$/.exec(tok);
    if (open) { stack.push(open[1]); out += tok; }
    else if (close) {
      while (stack.at(-1) !== close[1]) out += '</' + stack.pop() + '>';
      stack.pop();
      out += tok;
    } else out += tok;
  }
  while (stack.length) out += '</' + stack.pop() + '>';
  return out;
}
console.log(fixTags('<b><i>hi</b>there<u>x'));
```

