A user double-clicks **Resume**. The countdown now drops by 2 every second, Pause no longer stops it, and it goes below zero. What is the correct fix?

```js
function createCountdown(seconds, onTick) {
  let left = seconds, id = null;
  const tick = () => {
    left--;
    onTick(left);
    if (left === 0) clearInterval(id);
  };
  return {
    start()  { id = setInterval(tick, 1000); },
    pause()  { clearInterval(id); },
    resume() { id = setInterval(tick, 1000); },
  };
}
```

