class Store {
  constructor() { this.data = new Map(); this.stack = []; }
  get(k) {
    for (let i = this.stack.length - 1; i >= 0; i--) {
      if (this.stack[i].has(k)) return this.stack[i].get(k);
    }
    return this.data.get(k);
  }
  set(k, v) { (this.stack.at(-1) ?? this.data).set(k, v); }
  begin() { this.stack.push(new Map()); }
  rollback() { this.stack.pop(); }
  commit() {
    const top = this.stack.pop();
    const target = this.stack.at(-1) ?? this.data;
    for (const [k, v] of top) target.set(k, v);
  }
}
const s = new Store();
s.set('a', 1);
s.begin(); s.set('a', 2);
s.begin(); s.set('a', 3);
s.commit();
console.log(s.get('a'));
s.rollback();
console.log(s.get('a'));
```

