A minimal Observable has a `map` operator. After `sub.unsubscribe()` runs at 35 ms, what happens?

```js
class Observable {
  constructor(producer) { this.producer = producer; }
  subscribe(observer) {
    let closed = false;
    const teardown = this.producer({ next: (v) => { if (!closed) observer.next(v); } });
    return { unsubscribe() { closed = true; teardown?.(); } };
  }
  map(fn) {
    return new Observable((obs) => {
      this.subscribe({ next: (v) => obs.next(fn(v)) });
    });
  }
}
const ticks = new Observable((obs) => {
  let n = 0;
  const id = setInterval(() => obs.next(++n), 10);
  return () => clearInterval(id);
});
const sub = ticks.map((x) => x * 10).subscribe({ next: (v) => console.log(v) });
setTimeout(() => sub.unsubscribe(), 35);
```

