An autocomplete stores 100,000 words in this trie. Let p be the prefix length and k the number of trie nodes under the prefix. What are the costs of `startsWith(prefix)` and of collecting every completion?

```js
class Trie {
  root = {};
  insert(word) {
    let node = this.root;
    for (const ch of word) node = node[ch] ??= {};
    node.end = true;
  }
  startsWith(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      node = node[ch];
      if (!node) return false;
    }
    return true;
  }
}
